function parseSeeds(str) {
  const out = [];
  for (const part of str.split('|')) {
    const i = part.lastIndexOf(':');
    if (i < 1) continue;
    const text = part.slice(0, i).trim();
    const pct = parseFloat(part.slice(i + 1));
    if (text && !Number.isNaN(pct)) out.push({ text, pct });
  }
  return out;
}

function parseAliases(str) {
  const out = [];
  if (!str) return out;
  for (const part of str.split('|')) {
    const i = part.indexOf('=');
    if (i < 1) continue;
    out.push({ from: part.slice(0, i).trim(), to: part.slice(i + 1).trim() });
  }
  return out;
}

export const PROMPTS = RAW.map(([id, q, seeds, aliases]) => ({
  id,
  q,
  seeds: parseSeeds(seeds),
  aliases: parseAliases(aliases),
}));

export const PROMPT_BY_ID = Object.fromEntries(PROMPTS.map((p) => [p.id, p]));
